Given the root of a binary Tree, find the right view of the Binary Tree. The right view of a binary tree is a list of nodes you see when you look at the tree from the right side. It contains the rightmost node at each level, starting from the root (top level) down to the deepest level, in order.Examples: Input: Output: [1, 3, 4, 5]Explanation: The Green colored nodes (1, 3, 4, 5) represents the Right view in the below Binary tree. Input: Output: [1, 3, 5]Explanation: The Green colored nodes (1, 3, 5) represents the Right view in the below Binary tree Try It YourselfTable of Content[Expected Approach - 1] Using Recursion[Expected Approach – 2] Using Level Order Traversal – O(n) Time and O(n) Space[Expected Approach - 3] Using Morris Traversal – O(n) Time and O(1) Space [Expected Approach - 1] Using RecursionThe idea is to traverse the complete tree recursively. Because we need the right view, At each step, we first go to the right subtree and then to the left subtree. For each level, we store the first node we encounter (the rightmost node for that level). By traversing the entire tree this way, we ensure that every level contributes its rightmost node to the result.
            C++

    #include <iostream>
#include<vector>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// Function for the right view using Recursion
void recRightView(Node* root, int level, 
                        int& maxLevel, vector<int>& result) {
    if (!root) return;

    // If current level is more than max level,
    // this is the first node of that level
    if (level > maxLevel) {
        result.push_back(root->data);
        maxLevel = level;
    }

    // Traverse right subtree first, then left subtree
    recRightView(root->right, level + 1,
                       maxLevel, result);
    recRightView(root->left, level + 1,
                       maxLevel, result);
}

// Function to return the right view of the binary tree
vector<int> rightView(Node *root) {
    vector<int> result;
    int maxLevel = -1;

    // Start recursion with root at level 0
    recRightView(root, 0, maxLevel, result);

    return result;
}

int main() {

    // Representation of the input tree:
    //         1
    //        / \
    //       2   3
    //           / \   
    //          4   5  
    Node *root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->right->left = new Node(4);
    root->right->right = new Node(5);

    vector<int> result = rightView(root);

    for (int val : result) {
        cout << val << " ";
    }

    return 0;
}


