    #include <iostream>
#include <queue>
#include <vector>
using namespace std;

// Node Structure
class Node
{
  public:
    int data;
    Node *left;
    Node *right;

    Node(int x)
    {
        data = x;
        left = right = nullptr;
    }
};

vector<int> rightView(Node *root)
{
    vector<int> result;

    if (root == nullptr)
        return result;

    // Queue for level order traversal
    queue<Node *> q;
    q.push(root);

    while (!q.empty())
    {

        // Number of nodes at current level
        int levelSize = q.size();

        for (int i = 0; i < levelSize; i++)
        {
            Node *curr = q.front();
            q.pop();

            // If it's the last node of the current level
            if (i == levelSize - 1)
            {
                result.push_back(curr->data);
            }

            // Enqueue left child
            if (curr->left != nullptr)
            {
                q.push(curr->left);
            }

            // Enqueue right child
            if (curr->right != nullptr)
            {
                q.push(curr->right);
            }
        }
    }

    return result;
}

